using Normal.Realtime;

/// Synced state for a networked NPC. The authority (the one client simulating this NPC) publishes
/// its walking speed so every other client can play a locomotion animation without running the
/// NavMeshAgent. Mirrors PlayerAnimSyncModel; source-generated by Normcore (partial + [RealtimeModel]),
/// no "Compile Model" step.
///
/// Heavy per-NPC state (path, wander target, dwell) stays LOCAL to the authority and is NOT synced —
/// RealtimeTransform already carries the resulting position/rotation to remotes.
[RealtimeModel]
public partial class NpcSyncModel
{
    // Unreliable: only the latest value matters; a dropped packet is replaced by the next one, so
    // idle NPCs cost no retransmits (same rationale as PlayerAnimSyncModel._speed).
    [RealtimeProperty(1, false, false)] private float _speed;
}
